DO $$DECLARE rt text:=current_setting('sf.rt');sch text:=current_setting('sf.sch');r jsonb;r2 jsonb;i uuid;i2 uuid;i3 uuid;i4 uuid;i5 uuid;lease uuid;lease2 uuid;pid text;pt timestamptz:=now();BEGIN
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t2-red-call-start","contact_ref":"sp3t2-red-call-start","body":"hello"}');PERFORM set_consent(rt,'test-account',(r->>'contact_id')::uuid,'granted','sp3t2-red-call-start');r2:=complete_turn(rt,'test-account',(r->>'conversation_id')::uuid);ASSERT r2->>'terminal'='created','SP3-T2 fixture intent was not created: '||r2::text;i:=(r2->>'work_id')::uuid;
