 ASSERT(SELECT count(*)=1 AND min(event_type)='started'FROM provider_call_events WHERE(account_ref,intent_id)=('test-account',i)),'SP3-T2 append-only call-start evidence is missing';
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t2-red-pre-start","contact_ref":"sp3t2-red-pre-start","body":"hello"}');PERFORM set_consent(rt,'test-account',(r->>'contact_id')::uuid,'granted','sp3t2-red-pre-start');r2:=complete_turn(rt,'test-account',(r->>'conversation_id')::uuid);i2:=(r2->>'work_id')::uuid;r:=claim_dispatch(rt,'test-account',i2,now());lease:=(r->>'lease')::uuid;UPDATE intents SET lease_until=now()-interval'1 second'WHERE(account_ref,id)=('test-account',i2);r:=claim_dispatch(rt,'test-account',i2,now());ASSERT r->>'terminal'='claimed'AND(r->>'lease')::uuid<>lease,'SP3-T2 pre-start expired lease was not safely reclaimed: '||r::text;lease2:=(r->>'lease')::uuid;ASSERT NOT EXISTS(SELECT 1 FROM provider_calls WHERE(account_ref,intent_id)=('test-account',i2)),'SP3-T2 pre-start recovery created a provider call';r:=finish_dispatch(rt,'test-account',i2,lease2,'retryable');ASSERT r->>'terminal'='pending'AND r->>'next_attempt'IS NOT NULL,'SP3-T2 proven pre-start failure was not retryable: '||r::text;ASSERT EXISTS(SELECT 1 FROM intent_transitions WHERE(account_ref,intent_id,from_state,to_state,reason)=('test-account',i2,'leased','pending','pre_call_retryable')),'SP3-T2 pre-start retry history is missing';
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t2-red-post-start","contact_ref":"sp3t2-red-post-start","body":"hello"}');PERFORM set_consent(rt,'test-account',(r->>'contact_id')::uuid,'granted','sp3t2-red-post-start');r2:=complete_turn(rt,'test-account',(r->>'conversation_id')::uuid);i3:=(r2->>'work_id')::uuid;r:=claim_dispatch(rt,'test-account',i3,now());lease:=(r->>'lease')::uuid;r:=begin_provider_call(rt,'test-account',i3,lease);pid:=r->>'provider_id';UPDATE intents SET lease_until=now()-interval'1 second'WHERE(account_ref,id)=('test-account',i3);PERFORM count(*)FROM schedule_work(sch,now());ASSERT(SELECT state='reconciliation_required'AND reason='provider_call_outcome_unknown'FROM intents WHERE(account_ref,id)=('test-account',i3)),'SP3-T2 expired post-start call was not reconciled';ASSERT NOT EXISTS(SELECT 1 FROM schedule_work(sch,now())WHERE work_id=i3),'SP3-T2 uncertain post-start call was redispatched';r:=claim_dispatch(rt,'test-account',i3,now());ASSERT r->>'reason'='reconciliation_required','SP3-T2 uncertain post-start claim was not denied: '||r::text;ASSERT(SELECT count(*)=1 FROM provider_calls WHERE(account_ref,intent_id)=('test-account',i3)),'SP3-T2 uncertain post-start call duplicated';pt:=clock_timestamp();r:=callback(rt,jsonb_build_object('account_ref','test-account','event_id','sp3t2-reconcile-delivered','provider_id',pid,'status','delivered','provider_time',pt));ASSERT r->>'status'='delivered'AND(SELECT state='sent'AND provider_status='delivered'FROM intents WHERE(account_ref,id)=('test-account',i3)),'SP3-T2 authoritative callback did not resolve reconciliation: '||r::text;
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t2-red-terminal","contact_ref":"sp3t2-red-terminal","body":"hello"}');PERFORM set_consent(rt,'test-account',(r->>'contact_id')::uuid,'granted','sp3t2-red-terminal');r2:=complete_turn(rt,'test-account',(r->>'conversation_id')::uuid);i4:=(r2->>'work_id')::uuid;r:=claim_dispatch(rt,'test-account',i4,now());lease:=(r->>'lease')::uuid;r:=begin_provider_call(rt,'test-account',i4,lease);pid:=r->>'provider_id';r:=finish_dispatch(rt,'test-account',i4,lease,'success');ASSERT r->>'terminal'='sent'AND r->>'provider_id'=pid,'SP3-T2 successful call did not persist its durable provider identity: '||r::text;r:=claim_dispatch(rt,'test-account',i4,now());ASSERT r->>'reason'='already_sent','SP3-T2 terminal send replay was not typed: '||r::text;pt:=clock_timestamp();r:=callback(rt,jsonb_build_object('account_ref','test-account','event_id','sp3t2-terminal-delivered','provider_id',pid,'status','delivered','provider_time',pt));r:=callback(rt,jsonb_build_object('account_ref','test-account','event_id','sp3t2-terminal-old-sent','provider_id',pid,'status','sent','provider_time',pt-interval'1 minute'));r:=callback(rt,jsonb_build_object('account_ref','test-account','event_id','sp3t2-terminal-late-failed','provider_id',pid,'status','failed','provider_time',pt+interval'1 minute'));ASSERT(SELECT state='sent'AND provider_status='delivered'FROM intents WHERE(account_ref,id)=('test-account',i4)),'SP3-T2 terminal provider status regressed';ASSERT(SELECT count(*)=4 AND count(DISTINCT event_id)=4 FROM provider_events WHERE(account_ref,intent_id)=('test-account',i4)),'SP3-T2 accepted/delivered/out-of-order status history is incomplete';
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t2-red-failed","contact_ref":"sp3t2-red-failed","body":"hello"}');PERFORM set_consent(rt,'test-account',(r->>'contact_id')::uuid,'granted','sp3t2-red-failed');r2:=complete_turn(rt,'test-account',(r->>'conversation_id')::uuid);i5:=(r2->>'work_id')::uuid;r:=claim_dispatch(rt,'test-account',i5,now());lease:=(r->>'lease')::uuid;r:=begin_provider_call(rt,'test-account',i5,lease);pid:=r->>'provider_id';r:=finish_dispatch(rt,'test-account',i5,lease,'failed');ASSERT r->>'terminal'='failed'AND(SELECT provider_status='failed'AND reason='provider_call_failed'FROM intents WHERE(account_ref,id)=('test-account',i5)),'SP3-T2 conclusive provider failure was not durable: '||r::text;pt:=clock_timestamp();r:=callback(rt,jsonb_build_object('account_ref','test-account','event_id','sp3t2-failed-late-accepted','provider_id',pid,'status','accepted','provider_time',pt+interval'2 minutes'));ASSERT(SELECT state='failed'AND provider_status='failed'AND reason='provider_call_failed'FROM intents WHERE(account_ref,id)=('test-account',i5)),'SP3-T2 conclusive failure was resurrected by a later callback';ASSERT(SELECT count(*)=2 AND count(*)FILTER(WHERE status='failed')=1 AND count(*)FILTER(WHERE status='accepted')=1 FROM provider_events WHERE(account_ref,intent_id)=('test-account',i5)),'SP3-T2 failed and contradictory callback history is missing';r:=claim_dispatch(rt,'test-account',i5,now());ASSERT r->>'reason'='failed'AND(r->>'ok')::bool=false,'SP3-T2 failed terminal replay was not typed: '||r::text;
END$$;

-- SP3-T3: durable automatic follow-up, cancellation, stale completion, due dispatch,
-- and deletion-safe callback replay.
DO $sp3t3$
DECLARE rt text:='sp3t3-runtime-token';op text:='sp3t3-operator-token';sch text:=current_setting('sf.sch');r jsonb;r2 jsonb;source_work uuid;source_lease uuid;follow_work uuid;follow_lease uuid;orphan_work uuid;orphan_lease uuid:=gen_random_uuid();contact uuid;conv uuid;corr uuid;pid text;f followups;source_intent intents;payload jsonb;before_hash text;
BEGIN
 INSERT INTO accounts(id,enabled)VALUES('sp3t3-runtime',true);
 INSERT INTO controls(account_ref,key,value)VALUES('sp3t3-runtime','stop','{"enabled":false}');
 INSERT INTO config_docs(account_ref,kind,version,body,active)SELECT'sp3t3-runtime',kind,version,jsonb_set(body,'{accountRef}','"sp3t3-runtime"'),active FROM config_docs WHERE account_ref='test-account'AND active;
 INSERT INTO auth_tokens(hash,role,account_ref,actor,expires_at)VALUES(encode(digest(rt,'sha256'),'hex'),'runtime','sp3t3-runtime','sp3t3-runtime',now()+interval'1 day'),(encode(digest(op,'sha256'),'hex'),'operator','sp3t3-runtime','sp3t3-operator',now()+interval'1 day');
 r:=set_account_enabled(op,'sp3t3-runtime',false);ASSERT(r->>'ok')::bool AND NOT(SELECT enabled FROM accounts WHERE id='sp3t3-runtime'),'SP3-T3 account disable failed';r:=set_account_enabled(op,'sp3t3-runtime',true);ASSERT(r->>'ok')::bool AND(SELECT enabled FROM accounts WHERE id='sp3t3-runtime'),'SP3-T3 disabled account could not be restored through the narrow command';ASSERT set_account_enabled(op,'sp3t3-runtime',NULL)->>'reason'='invalid_input','SP3-T3 NULL account enabled value escaped typed validation';ASSERT set_control(op,'sp3t3-runtime','stop','{}')->>'reason'='invalid_control','SP3-T3 missing stop enabled field was accepted';ASSERT set_control(op,NULL,'stop','{"enabled":false}')->>'reason'='unauthorized'AND set_control(op,'sp3t3-runtime',NULL,'{"enabled":false}')->>'reason'='unauthorized'AND set_control(op,'sp3t3-runtime','other','{"enabled":false}')->>'reason'='unauthorized','SP3-T3 malformed control scope escaped typed unauthorized';ASSERT set_control(op,'sp3t3-runtime','stop',NULL)->>'reason'='invalid_control','SP3-T3 malformed control body escaped typed invalid_control';ASSERT has_function_privilege('salesflow_runtime','salesflow.set_account_enabled(text,text,boolean)','EXECUTE')AND has_function_privilege('salesflow_runtime','salesflow.set_control(text,text,text,jsonb)','EXECUTE')AND has_function_privilege('salesflow_runtime','salesflow.set_conversation_state(text,text,uuid,text,text,boolean)','EXECUTE'),'SP3-T3 authenticated runtime role lacks an approved operational command grant';
 ASSERT EXISTS(SELECT 1 FROM config_docs c CROSS JOIN LATERAL jsonb_array_elements(c.body->'templates')x WHERE c.account_ref='sp3t3-runtime'AND c.kind='consent_templates'AND c.active AND x->>'key'='followup-en'AND x->>'providerTemplateId'='followup-en'AND x->>'category'='marketing'AND x->>'language'='en'),'SP3-T3 approved provider template metadata missing';ASSERT NOT validate_config('consent_templates','{"accountRef":"sp3t3-runtime","kind":"consent_templates","version":"bad-template","serviceWindowHours":24,"optOutSignals":["stop"],"humanSignals":["human"],"templates":[{"key":"followup-en","approved":true,"windowHours":24}]}'),'SP3-T3 template metadata was optional';

 r:=ingest(rt,jsonb_build_object('account_ref','sp3t3-runtime','provider_id','sp3t3-auto-source','contact_ref','sp3t3-auto','body','hello'));contact:=(r->>'contact_id')::uuid;conv:=(r->>'conversation_id')::uuid;PERFORM set_consent(rt,'sp3t3-runtime',contact,'granted','sp3t3 auto consent');r2:=complete_turn(rt,'sp3t3-runtime',conv);source_work:=(r2->>'work_id')::uuid;r2:=claim_dispatch(rt,'sp3t3-runtime',source_work,now());source_lease:=(r2->>'lease')::uuid;PERFORM begin_provider_call(rt,'sp3t3-runtime',source_work,source_lease);ASSERT(SELECT started_at>transaction_timestamp()FROM provider_calls WHERE(account_ref,intent_id)=('sp3t3-runtime',source_work)),'SP3-T3 provider call used transaction-start time';r2:=finish_dispatch(rt,'sp3t3-runtime',source_work,source_lease,'success');ASSERT r2->>'terminal'='sent';SELECT*INTO f FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work;ASSERT FOUND AND f.state='due'AND followup_evidence_valid(f)AND f.due_at=f.scheduled_from_sent_at+interval'12 hours'AND f.scheduled_from_sent_at>transaction_timestamp()AND f.scheduled_from_sent_at=(SELECT provider_time FROM intents WHERE(account_ref,id)=('sp3t3-runtime',source_work))AND f.scheduled_from_sent_at=(SELECT at FROM intent_transitions WHERE(account_ref,intent_id,to_state,reason)=('sp3t3-runtime',source_work,'sent','provider_accepted')),'SP3-T3 automatic +12-hour durable sent-time evidence failed';f.request_hash:=NULL;ASSERT followup_evidence_valid(f)IS FALSE,'SP3-T3 nullable evidence did not fail closed';SELECT*INTO f FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work;f.action_key:=f.action_key||'-tampered';ASSERT followup_evidence_valid(f)IS FALSE,'SP3-T3 actionKey was not request-hash bound';SELECT*INTO f FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work;f.source_conversation_version:=f.source_conversation_version+1;ASSERT followup_evidence_valid(f)IS FALSE,'SP3-T3 sourceConversationVersion was not request-hash bound';SELECT*INTO f FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work;f.template_key:='tampered-template';ASSERT followup_evidence_valid(f)IS FALSE,'SP3-T3 templateKey was not request-hash bound';SELECT*INTO f FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work;BEGIN ALTER TABLE contact_identifiers DISABLE TRIGGER contact_identifier_immutable;UPDATE contact_identifiers SET active=false,retired_at=clock_timestamp()WHERE(account_ref,contact_id,channel,provider)=('sp3t3-runtime',contact,'whatsapp','meta')AND active;ASSERT followup_due_authorization_reason(f)='contact_identifier_missing','SP3-T3 due authorization ignored missing current WhatsApp Meta identity';RAISE EXCEPTION'rollback missing Meta identity';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback missing Meta identity'THEN RAISE;END IF;END;SELECT*INTO source_intent FROM intents WHERE(account_ref,id)=('sp3t3-runtime',source_work);source_intent.provenance:=jsonb_set(source_intent.provenance,'{context,consentOccurredAt}','"not-a-timestamp"');ASSERT followup_schedule_authorization_reason(source_intent)='consent_changed','SP3-T3 malformed consent timestamp did not return a typed denial';ASSERT finish_dispatch(rt,'sp3t3-runtime',source_work,source_lease,NULL)->>'reason'='invalid_outcome','SP3-T3 NULL completion outcome was accepted';PERFORM finish_dispatch(rt,'sp3t3-runtime',source_work,source_lease,'success');ASSERT(SELECT count(*)=1 FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work),'SP3-T3 completion replay duplicated a follow-up';
 r:=ingest(rt,jsonb_build_object('account_ref','sp3t3-runtime','provider_id','sp3t3-auto-reply','contact_ref','sp3t3-auto','body','thanks'));SELECT*INTO f FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work;ASSERT f.state='cancelled'AND f.reason='customer_replied','SP3-T3 reply did not cancel with exact reason';BEGIN UPDATE followups SET reason='changed'WHERE(account_ref,id)=(f.account_ref,f.id);ASSERT false;EXCEPTION WHEN raise_exception THEN NULL;END;

 r:=ingest(rt,jsonb_build_object('account_ref','sp3t3-runtime','provider_id','sp3t3-stale-source','contact_ref','sp3t3-stale','body','hello'));PERFORM set_consent(rt,'sp3t3-runtime',(r->>'contact_id')::uuid,'granted','sp3t3 stale consent');conv:=(r->>'conversation_id')::uuid;r2:=complete_turn(rt,'sp3t3-runtime',conv);source_work:=(r2->>'work_id')::uuid;r2:=claim_dispatch(rt,'sp3t3-runtime',source_work,now());source_lease:=(r2->>'lease')::uuid;PERFORM begin_provider_call(rt,'sp3t3-runtime',source_work,source_lease);PERFORM ingest(rt,jsonb_build_object('account_ref','sp3t3-runtime','provider_id','sp3t3-stale-newer','contact_ref','sp3t3-stale','body','newer'));PERFORM finish_dispatch(rt,'sp3t3-runtime',source_work,source_lease,'success');ASSERT NOT EXISTS(SELECT 1 FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work),'SP3-T3 stale sent completion scheduled a follow-up';ASSERT EXISTS(SELECT 1 FROM audit_events WHERE account_ref='sp3t3-runtime'AND event='followup_not_scheduled'AND reason='stale_version'AND details->>'sourceIntentId'=source_work::text),'SP3-T3 stale sent completion reason missing';

 r:=ingest(rt,jsonb_build_object('account_ref','sp3t3-runtime','provider_id','sp3t3-due-source','contact_ref','sp3t3-due','body','hello'));contact:=(r->>'contact_id')::uuid;conv:=(r->>'conversation_id')::uuid;PERFORM set_consent(rt,'sp3t3-runtime',contact,'granted','sp3t3 due consent');r2:=complete_turn(rt,'sp3t3-runtime',conv);source_work:=(r2->>'work_id')::uuid;source_lease:=gen_random_uuid();corr:=gen_random_uuid();pid:='synthetic-'||source_work::text;UPDATE intents SET state='leased',lease=source_lease,lease_until=clock_timestamp()+interval'1 hour',attempts=1 WHERE(account_ref,id)=('sp3t3-runtime',source_work);INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,correlation_id,release_set_version,callback_alias,started_at)SELECT account_ref,id,1,source_lease,pid,corr,provenance#>>'{context,releaseSetVersion}',encode(digest(account_ref||':'||pid,'sha256'),'hex'),clock_timestamp()-interval'13 hours'FROM intents WHERE(account_ref,id)=('sp3t3-runtime',source_work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES('sp3t3-runtime',source_work,'leased','sent','fixture_durable_sent',clock_timestamp()-interval'13 hours');UPDATE intents SET state='sent',provider_id=pid,provider_status='accepted',provider_time=clock_timestamp()-interval'30 days',lease=NULL,lease_until=NULL WHERE(account_ref,id)=('sp3t3-runtime',source_work);SELECT*INTO f FROM followups WHERE account_ref='sp3t3-runtime'AND source_intent_id=source_work;ASSERT f.due_at<=clock_timestamp();BEGIN ALTER TABLE config_docs DISABLE TRIGGER config_immutable;UPDATE config_docs SET body=jsonb_set(body,'{serviceWindowHours}','1'::jsonb)WHERE account_ref='sp3t3-runtime'AND kind='consent_templates'AND active;ASSERT followup_due_authorization_reason(f,clock_timestamp())='authorized','SP3-T3 approved template was rejected outside service window but inside template window';RAISE EXCEPTION'rollback followup service-window fixture';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback followup service-window fixture'THEN RAISE;END IF;END;ASSERT followup_due_authorization_reason(f,clock_timestamp()+interval'25 hours')='template_window_closed','SP3-T3 expired template window remained authorized';SELECT work_id INTO follow_work FROM schedule_followups(sch,clock_timestamp())WHERE account_ref='sp3t3-runtime';ASSERT follow_work IS NOT NULL,'SP3-T3 due job produced no work';ASSERT followup_final_authorization_reason('sp3t3-runtime',follow_work)='authorized','SP3-T3 final retry boundary rejected the scheduled attempt';BEGIN ALTER TABLE intents DISABLE TRIGGER intent_evidence_immutable;UPDATE intents SET provenance=provenance#-'{context,followupCorrelationId}'WHERE(account_ref,id)=('sp3t3-runtime',follow_work);ASSERT followup_final_authorization_reason('sp3t3-runtime',follow_work)='followup_evidence_invalid','SP3-T3 missing child correlation binding passed final authorization';RAISE EXCEPTION'rollback malformed child provenance';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback malformed child provenance'THEN RAISE;END IF;END;r2:=claim_dispatch(rt,'sp3t3-runtime',follow_work,now());follow_lease:=(r2->>'lease')::uuid;BEGIN r2:=finish_dispatch(rt,'sp3t3-runtime',follow_work,follow_lease,'retryable');ASSERT r2->>'terminal'='pending'AND(SELECT state='retry'FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id))AND NOT EXISTS(SELECT 1 FROM schedule_work(sch,clock_timestamp())WHERE work_id=follow_work),'SP3-T3 retry child escaped while its parent remained retry';RAISE EXCEPTION'rollback retry parent gate fixture';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback retry parent gate fixture'THEN RAISE;END IF;END;BEGIN UPDATE intents SET attempts=3 WHERE(account_ref,id)=('sp3t3-runtime',follow_work);r2:=finish_dispatch(rt,'sp3t3-runtime',follow_work,follow_lease,'retryable');ASSERT r2->>'terminal'='suppressed'AND(SELECT state='suppressed'AND reason='retry_exhausted'FROM intents WHERE(account_ref,id)=('sp3t3-runtime',follow_work))AND(SELECT state='exhausted'FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id))AND NOT EXISTS(SELECT 1 FROM provider_calls WHERE(account_ref,intent_id)=('sp3t3-runtime',follow_work)),'SP3-T3 pre-call exhaustion falsely required reconciliation';RAISE EXCEPTION'rollback pre-call exhaustion fixture';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback pre-call exhaustion fixture'THEN RAISE;END IF;END;r2:=begin_provider_call(rt,'sp3t3-runtime',follow_work,follow_lease);ASSERT r2->>'terminal'='started'AND(SELECT state='call_started'FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id)),'SP3-T3 parent was not call_started before provider exposure';pid:=r2->>'provider_id';ASSERT finish_dispatch(rt,'sp3t3-runtime',follow_work,NULL,'success')->>'reason'='call_mismatch','SP3-T3 NULL lease completed another worker call';BEGIN r2:=finish_dispatch(rt,'sp3t3-runtime',follow_work,follow_lease,'ambiguous');ASSERT r2->>'terminal'='reconciliation_required';r2:=finish_dispatch(rt,'sp3t3-runtime',follow_work,follow_lease,'ambiguous');ASSERT r2->>'terminal'='reconciliation_required'AND(SELECT count(*)=1 FROM intent_transitions WHERE(account_ref,intent_id,to_state,reason)=('sp3t3-runtime',follow_work,'reconciliation_required','ambiguous'))AND(SELECT count(*)=1 FROM followup_transitions WHERE(account_ref,followup_id,to_state,reason)=('sp3t3-runtime',f.id,'reconciliation_required','ambiguous')),'SP3-T3 ambiguous completion replay duplicated transition evidence';RAISE EXCEPTION'rollback ambiguous replay fixture';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback ambiguous replay fixture'THEN RAISE;END IF;END;BEGIN r:=callback(rt,jsonb_build_object('account_ref','sp3t3-runtime','event_id','sp3t3-callback-failed','provider_id',pid,'status','failed','provider_time',clock_timestamp()));ASSERT r->>'status'='failed'AND(SELECT state='failed'AND reason='provider_failed'FROM intents WHERE(account_ref,id)=('sp3t3-runtime',follow_work))AND(SELECT state='failed'FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id)),'SP3-T3 callback failure did not become terminal';r:=callback(rt,jsonb_build_object('account_ref','sp3t3-runtime','event_id','sp3t3-callback-late-accepted','provider_id',pid,'status','accepted','provider_time',clock_timestamp()+interval'1 second'));ASSERT(SELECT state='failed'AND reason='provider_failed'AND provider_status='failed'FROM intents WHERE(account_ref,id)=('sp3t3-runtime',follow_work))AND(SELECT state='failed'FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id)),'SP3-T3 callback-created failure was resurrected';RAISE EXCEPTION'rollback callback failure fixture';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback callback failure fixture'THEN RAISE;END IF;END;r2:=finish_dispatch(rt,'sp3t3-runtime',follow_work,follow_lease,'success');ASSERT(SELECT provider_time>transaction_timestamp()FROM intents WHERE(account_ref,id)=('sp3t3-runtime',follow_work)),'SP3-T3 completion used transaction-start time';ASSERT r2->>'terminal'='sent'AND(SELECT state='sent'FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id))AND(SELECT max(at)FROM followup_transitions WHERE(account_ref,followup_id,to_state)=('sp3t3-runtime',f.id,'sent'))<=(SELECT max(at)FROM intent_transitions WHERE(account_ref,intent_id,to_state)=('sp3t3-runtime',follow_work,'sent'))AND(SELECT count(*)=1 FROM provider_calls WHERE(account_ref,intent_id)=('sp3t3-runtime',follow_work)),'SP3-T3 no-reply branch was not exactly-once sent';

 ALTER TABLE intents DISABLE TRIGGER intent_source_context;
 INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance,state,lease,lease_until,attempts)SELECT account_ref,contact_id,conversation_id,gen_random_uuid(),'followup',expected_version,policy_version,knowledge_version,body,template_key,provenance,'leased',orphan_lease,clock_timestamp()+interval'1 hour',1 FROM intents WHERE(account_ref,id)=('sp3t3-runtime',follow_work)RETURNING id INTO orphan_work;
 ALTER TABLE intents ENABLE TRIGGER intent_source_context;
 r2:=finish_dispatch(rt,'sp3t3-runtime',orphan_work,orphan_lease,'retryable');ASSERT r2->>'terminal'='denied'AND r2->>'reason'='followup_parent_missing'AND(SELECT state='suppressed'AND reason='followup_parent_missing'FROM intents WHERE(account_ref,id)=('sp3t3-runtime',orphan_work))AND EXISTS(SELECT 1 FROM intent_transitions WHERE(account_ref,intent_id,to_state,reason)=('sp3t3-runtime',orphan_work,'suppressed','followup_parent_missing')),'SP3-T3 orphan retryable child returned to pending';
 SELECT provider_id INTO pid FROM provider_calls WHERE(account_ref,intent_id)=('sp3t3-runtime',follow_work);payload:=jsonb_build_object('account_ref','sp3t3-runtime','event_id','sp3t3-delete-replay','provider_id',pid,'status','delivered','provider_time',clock_timestamp());r:=callback(rt,payload);ASSERT(r->>'created')::bool AND(SELECT state='delivered'FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id)),'SP3-T3 sent parent did not advance to delivered';SELECT payload_hash INTO before_hash FROM provider_events WHERE(account_ref,event_id)=('sp3t3-runtime','sp3t3-delete-replay');r:=operations(op,'sp3t3-runtime',jsonb_build_object('action','delete','contact_id',contact));ASSERT r->>'terminal'='deleted';ASSERT(SELECT payload_hash=before_hash FROM provider_events WHERE(account_ref,event_id)=('sp3t3-runtime','sp3t3-delete-replay')),'SP3-T3 deletion changed callback fingerprint';r:=callback(rt,payload);ASSERT(r->>'created')::bool=false,'SP3-T3 post-delete replay did not deduplicate';r:=callback(rt,jsonb_set(payload,'{provider_id}',to_jsonb('deleted-'||follow_work::text)));ASSERT r->>'reason'='provider_mismatch','SP3-T3 predictable tombstone callback was accepted';BEGIN DELETE FROM followups WHERE(account_ref,id)=('sp3t3-runtime',f.id);ASSERT false;EXCEPTION WHEN raise_exception THEN NULL;END;
 ASSERT(followup_metrics('sp3t3-runtime')?&ARRAY['followupBacklog','oldestFollowupDueAgeSeconds','followupRetry','followupExhausted'])AND(followup_metrics('sp3t3-runtime')->>'oldestFollowupDueAgeSeconds')::numeric>=0,'SP3-T3 operator metrics incomplete or negative';
END$sp3t3$;

DO $sp3t3_orphan_truth$
DECLARE rt text:='sp3t3-runtime-token';base intents;started_work uuid;sent_work uuid;lease_id uuid:=gen_random_uuid();pid text;release_version text;r jsonb;
BEGIN
 ALTER TABLE intents DISABLE TRIGGER intent_source_context;
 SELECT*INTO base FROM intents WHERE account_ref='sp3t3-runtime'AND kind='followup'ORDER BY id LIMIT 1;SELECT version INTO release_version FROM config_docs WHERE account_ref=base.account_ref AND kind='release_set'AND active;INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance,state,lease,lease_until,attempts)VALUES(base.account_ref,base.contact_id,base.conversation_id,gen_random_uuid(),'followup',base.expected_version,base.policy_version,base.knowledge_version,base.body,base.template_key,base.provenance,'provider_call_started',lease_id,clock_timestamp()+interval'1 hour',1)RETURNING id INTO started_work;pid:='orphan-started-'||started_work::text;INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,correlation_id,release_set_version,callback_alias,started_at)VALUES(base.account_ref,started_work,1,lease_id,pid,gen_random_uuid(),release_version,encode(digest(base.account_ref||':'||pid,'sha256'),'hex'),clock_timestamp());r:=claim_dispatch(rt,base.account_ref,started_work,clock_timestamp());ASSERT r->>'terminal'='reconciliation_required'AND(SELECT state='reconciliation_required'AND reason='followup_parent_missing'FROM intents WHERE(account_ref,id)=(base.account_ref,started_work))AND EXISTS(SELECT 1 FROM intent_transitions WHERE(account_ref,intent_id,to_state,reason)=(base.account_ref,started_work,'reconciliation_required','followup_parent_missing'))AND EXISTS(SELECT 1 FROM provider_call_events WHERE(account_ref,intent_id,event_type,reason)=(base.account_ref,started_work,'reconciliation_required','followup_parent_missing')),'SP3-T3 started orphan lost reconciliation evidence';INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance,state,attempts,provider_status,provider_time)VALUES(base.account_ref,base.contact_id,base.conversation_id,gen_random_uuid(),'followup',base.expected_version,base.policy_version,base.knowledge_version,base.body,base.template_key,base.provenance,'sent',1,'accepted',clock_timestamp())RETURNING id INTO sent_work;pid:='orphan-sent-'||sent_work::text;INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,correlation_id,release_set_version,callback_alias,started_at)VALUES(base.account_ref,sent_work,1,gen_random_uuid(),pid,gen_random_uuid(),release_version,encode(digest(base.account_ref||':'||pid,'sha256'),'hex'),clock_timestamp());r:=callback(rt,jsonb_build_object('account_ref',base.account_ref,'event_id','orphan-sent-late-failed','provider_id',pid,'status','failed','provider_time',clock_timestamp()));ASSERT r->>'terminal'='sent'AND(SELECT state='sent'FROM intents WHERE(account_ref,id)=(base.account_ref,sent_work))AND NOT EXISTS(SELECT 1 FROM intent_transitions WHERE(account_ref,intent_id,to_state)=(base.account_ref,sent_work,'reconciliation_required')),'SP3-T3 conclusive sent orphan regressed during callback';
 INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance,state,reason,attempts,provider_status,provider_time)VALUES(base.account_ref,base.contact_id,base.conversation_id,gen_random_uuid(),'followup',base.expected_version,base.policy_version,base.knowledge_version,base.body,base.template_key,base.provenance,'failed','provider_failed',1,'failed',clock_timestamp())RETURNING id INTO sent_work;pid:='orphan-failed-'||sent_work::text;INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,correlation_id,release_set_version,callback_alias,started_at)VALUES(base.account_ref,sent_work,1,gen_random_uuid(),pid,gen_random_uuid(),release_version,encode(digest(base.account_ref||':'||pid,'sha256'),'hex'),clock_timestamp());r:=callback(rt,jsonb_build_object('account_ref',base.account_ref,'event_id','orphan-failed-late-accepted','provider_id',pid,'status','accepted','provider_time',clock_timestamp()));ASSERT r->>'terminal'='failed'AND(SELECT state='failed'AND reason='provider_failed'FROM intents WHERE(account_ref,id)=(base.account_ref,sent_work)),'SP3-T3 conclusive failed orphan regressed during callback';
 ALTER TABLE intents ENABLE TRIGGER intent_source_context;
END$sp3t3_orphan_truth$;

DO $sp3t3_contract_evidence$
DECLARE rt text:='sp3t3-contract-token';sch text:=current_setting('sf.sch');acct text:='sp3t3-contract';r jsonb;r2 jsonb;contact uuid;conv uuid;source_work uuid;source_lease uuid;follow_work uuid;new_work uuid;new_lease uuid;f followups;hr int:=extract(hour FROM clock_timestamp()AT TIME ZONE'UTC');
BEGIN
 INSERT INTO accounts(id,enabled)VALUES(acct,true);INSERT INTO controls(account_ref,key,value)VALUES(acct,'stop','{"enabled":false}');INSERT INTO config_docs(account_ref,kind,version,body,active)SELECT acct,kind,version,jsonb_set(body,'{accountRef}',to_jsonb(acct)),active FROM config_docs WHERE account_ref='test-account'AND active;INSERT INTO auth_tokens(hash,role,account_ref,actor,expires_at)VALUES(encode(digest(rt,'sha256'),'hex'),'runtime',acct,'sp3t3-contract',clock_timestamp()+interval'1 day');
 r:=ingest(rt,jsonb_build_object('account_ref',acct,'provider_id','sp3t3-contract-source','contact_ref','sp3t3-contract','body','hello'));contact:=(r->>'contact_id')::uuid;conv:=(r->>'conversation_id')::uuid;PERFORM set_consent(rt,acct,contact,'granted','sp3t3 contract consent');r2:=complete_turn(rt,acct,conv);source_work:=(r2->>'work_id')::uuid;source_lease:=gen_random_uuid();UPDATE intents SET state='leased',lease=source_lease,lease_until=clock_timestamp()+interval'1 hour',attempts=1 WHERE(account_ref,id)=(acct,source_work);INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,correlation_id,release_set_version,callback_alias,started_at)SELECT account_ref,id,1,source_lease,'synthetic-'||id::text,gen_random_uuid(),provenance#>>'{context,releaseSetVersion}',encode(digest(account_ref||':synthetic-'||id::text,'sha256'),'hex'),clock_timestamp()-interval'13 hours'FROM intents WHERE(account_ref,id)=(acct,source_work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES(acct,source_work,'leased','sent','sp3t3_contract_fixture',clock_timestamp()-interval'13 hours');UPDATE intents SET state='sent',provider_id='synthetic-'||id::text,provider_status='accepted',provider_time=clock_timestamp()-interval'13 hours',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,source_work);SELECT*INTO f FROM followups WHERE(account_ref,source_intent_id)=(acct,source_work);
 BEGIN DELETE FROM controls WHERE(account_ref,key)=(acct,'stop');ASSERT followup_due_authorization_reason(f)='missing_control','SP3-T3 due missing-control reason not exact';RAISE EXCEPTION'rollback missing control';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback missing control'THEN RAISE;END IF;END;
 BEGIN ALTER TABLE config_docs DISABLE TRIGGER config_immutable;UPDATE config_docs SET active=false WHERE account_ref=acct AND kind='release_set'AND active;ASSERT followup_due_authorization_reason(f)='inconsistent_business_context','SP3-T3 due business-context reason not exact';RAISE EXCEPTION'rollback business context';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback business context'THEN RAISE;END IF;END;
 BEGIN ALTER TABLE config_docs DISABLE TRIGGER config_immutable;UPDATE config_docs SET body=jsonb_set(body,'{templates,0,category}','"utility"')WHERE account_ref=acct AND kind='consent_templates'AND active;ASSERT followup_due_authorization_reason(f)='template_invalid','SP3-T3 due template reason not exact';RAISE EXCEPTION'rollback template invalid';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback template invalid'THEN RAISE;END IF;END;
 BEGIN ALTER TABLE config_docs DISABLE TRIGGER config_immutable;UPDATE config_docs SET body=jsonb_set(jsonb_set(body,'{quietHoursUtc,start}',to_jsonb(hr)),'{quietHoursUtc,end}',to_jsonb((hr+1)%24))WHERE account_ref=acct AND kind='sales_policy'AND active;ASSERT followup_due_authorization_reason(f)='quiet_hours','SP3-T3 due quiet-hours reason not exact';RAISE EXCEPTION'rollback quiet hours';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback quiet hours'THEN RAISE;END IF;END;
 BEGIN ALTER TABLE config_docs DISABLE TRIGGER config_immutable;UPDATE config_docs SET body=jsonb_set(body,'{frequencyCap24h}','0')WHERE account_ref=acct AND kind='sales_policy'AND active;ASSERT followup_due_authorization_reason(f)='frequency_cap','SP3-T3 due frequency-cap reason not exact';RAISE EXCEPTION'rollback frequency cap';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback frequency cap'THEN RAISE;END IF;END;
 SELECT work_id INTO follow_work FROM schedule_followups(sch,clock_timestamp())WHERE account_ref=acct;ASSERT follow_work IS NOT NULL;
 ALTER TABLE inbound_messages DISABLE TRIGGER cancel_followups_after_inbound;r:=ingest(rt,jsonb_build_object('account_ref',acct,'provider_id','sp3t3-contract-newer','contact_ref','sp3t3-contract','body','new question'));ALTER TABLE inbound_messages ENABLE TRIGGER cancel_followups_after_inbound;r2:=complete_turn(rt,acct,conv);new_work:=(r2->>'work_id')::uuid;r2:=claim_dispatch(rt,acct,new_work,clock_timestamp());new_lease:=(r2->>'lease')::uuid;PERFORM begin_provider_call(rt,acct,new_work,new_lease);PERFORM finish_dispatch(rt,acct,new_work,new_lease,'success');ASSERT(SELECT state='superseded'AND reason='newer_sent_reply'FROM followups WHERE(account_ref,id)=(acct,f.id))AND(SELECT state='suppressed'AND reason='newer_sent_reply'FROM intents WHERE(account_ref,id)=(acct,follow_work))AND(SELECT count(*)=1 FROM followups WHERE account_ref=acct AND source_intent_id=new_work AND state='due')AND(SELECT count(DISTINCT source_intent_id)=2 FROM followups WHERE account_ref=acct),'SP3-T3 newer sent reply did not supersede exactly one older active reminder with both source identities';PERFORM cancel_followups_for_conversation(acct,conv,'test_cleanup',NULL);
END$sp3t3_contract_evidence$;

DO $sp3t3_metrics$
DECLARE c1 uuid;c2 uuid;c3 uuid;c4 uuid;v1 uuid;v2 uuid;v3 uuid;v4 uuid;m jsonb;
BEGIN
 INSERT INTO accounts(id,enabled)VALUES('sp3t3-metrics',true);INSERT INTO contacts(account_ref)VALUES('sp3t3-metrics')RETURNING id INTO c1;INSERT INTO contacts(account_ref)VALUES('sp3t3-metrics')RETURNING id INTO c2;INSERT INTO contacts(account_ref)VALUES('sp3t3-metrics')RETURNING id INTO c3;INSERT INTO contacts(account_ref)VALUES('sp3t3-metrics')RETURNING id INTO c4;INSERT INTO conversations(account_ref,contact_id)VALUES('sp3t3-metrics',c1)RETURNING id INTO v1;INSERT INTO conversations(account_ref,contact_id)VALUES('sp3t3-metrics',c2)RETURNING id INTO v2;INSERT INTO conversations(account_ref,contact_id)VALUES('sp3t3-metrics',c3)RETURNING id INTO v3;INSERT INTO conversations(account_ref,contact_id)VALUES('sp3t3-metrics',c4)RETURNING id INTO v4;INSERT INTO followups(account_ref,contact_id,conversation_id,due_at,expected_version,state,next_attempt)VALUES('sp3t3-metrics',c1,v1,clock_timestamp()-interval'2 minutes',0,'due',NULL),('sp3t3-metrics',c2,v2,clock_timestamp()-interval'1 minute',0,'retry',clock_timestamp()),('sp3t3-metrics',c3,v3,clock_timestamp()-interval'3 minutes',0,'exhausted',NULL),('sp3t3-metrics',c4,v4,clock_timestamp()+interval'1 hour',0,'due',NULL);m:=followup_metrics('sp3t3-metrics');ASSERT(m->>'followupBacklog')::int=3 AND(m->>'followupRetry')::int=1 AND(m->>'followupExhausted')::int=1 AND(m->>'oldestFollowupDueAgeSeconds')::numeric>=120 AND(m->>'oldestFollowupDueAgeSeconds')::numeric<130,'SP3-T3 exact operator metrics do not match controlled state';PERFORM transition_followup_parent_first(f.account_ref,f.id,'suppressed','test_cleanup','{}')FROM followups f WHERE f.account_ref='sp3t3-metrics'AND f.state IN('due','claimed','retry','intent_created');
END$sp3t3_metrics$;

INSERT INTO accounts(id,enabled)VALUES('sp3t3-starvation',true);
INSERT INTO controls(account_ref,key,value)VALUES('sp3t3-starvation','stop','{"enabled":false}');
INSERT INTO config_docs(account_ref,kind,version,body,active)SELECT'sp3t3-starvation',kind,version,jsonb_set(body,'{accountRef}','"sp3t3-starvation"'),active FROM config_docs WHERE account_ref='test-account'AND active;
DO $sp3t3_starvation_fixture$
DECLARE idx int;c uuid;v uuid;m uuid;s uuid;fid uuid;corr uuid;due timestamptz;sent_at timestamptz;release_version text;policy_version text;knowledge_version text;consent_at timestamptz;consent_hash text;campaign_id text;campaign_data jsonb;request_payload jsonb;
BEGIN
 SELECT version,body->>'policyVersion',body->>'knowledgeVersion'INTO release_version,policy_version,knowledge_version FROM config_docs WHERE account_ref='sp3t3-starvation'AND kind='release_set'AND active;
 FOR idx IN 1..201 LOOP
  INSERT INTO contacts(account_ref)VALUES('sp3t3-starvation')RETURNING id INTO c;INSERT INTO contact_identifiers(account_ref,contact_id,channel,provider,external_ref,external_ref_hash)VALUES('sp3t3-starvation',c,'whatsapp','meta','sp3t3-starve-contact-'||idx,encode(digest('sp3t3-starve-contact-'||idx,'sha256'),'hex'));INSERT INTO conversations(account_ref,contact_id)VALUES('sp3t3-starvation',c)RETURNING id INTO v;INSERT INTO inbound_messages(account_ref,conversation_id,provider_id,contact_ref,body,processing_body,body_hash,received_at,seq)VALUES('sp3t3-starvation',v,'sp3t3-starve-in-'||idx,'sp3t3-starve-contact-'||idx,'hello','hello',encode(digest('hello','sha256'),'hex'),clock_timestamp(),0)RETURNING id INTO m;consent_at:=clock_timestamp();INSERT INTO consent_events VALUES('sp3t3-starvation',c,'granted','sp3t3-starve-consent-'||idx,consent_at);consent_hash:=encode(digest('sp3t3-starve-consent-'||idx,'sha256'),'hex');s:=gen_random_uuid();corr:=gen_random_uuid();due:=clock_timestamp()-interval'3 hours'+idx*interval'1 second';sent_at:=due-interval'12 hours';campaign_id:='sp3t3-starvation:'||v::text||':'||release_version;campaign_data:=jsonb_build_object('conversationEnabled',true,'policyEnabled',true);
  INSERT INTO intents(account_ref,id,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,provenance,state,provider_id,provider_status,provider_time)VALUES('sp3t3-starvation',s,c,v,m,'reply',1,policy_version,knowledge_version,'reply',jsonb_build_object('context',jsonb_build_object('releaseSetVersion',release_version,'consentOccurredAt',consent_at,'consentEvidenceHash',consent_hash)),'sent','sp3t3-starve-provider-'||idx,'accepted',sent_at);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES('sp3t3-starvation',s,'provider_call_started','sent','provider_accepted',sent_at);INSERT INTO provider_calls(account_ref,intent_id,attempt_no,lease,provider_id,correlation_id,release_set_version,callback_alias,started_at)VALUES('sp3t3-starvation',s,1,gen_random_uuid(),'sp3t3-starve-provider-'||idx,corr,release_version,encode(digest('sp3t3-starvation:sp3t3-starve-provider-'||idx,'sha256'),'hex'),sent_at);
  request_payload:=followup_request_payload('sp3t3-starvation',s,c,v,due,1,release_version,policy_version,knowledge_version,consent_at,consent_hash,'followup-en',corr,1,campaign_id,campaign_data,'sp3t3-starve-'||lpad(idx::text,3,'0'),1,'followup-en');fid:=gen_random_uuid();INSERT INTO followups(account_ref,id,contact_id,conversation_id,due_at,expected_version,template_key,state,source_intent_id,action_key,request_hash,generation,source_conversation_version,scheduled_from_sent_at,release_set_version,policy_version,knowledge_version,consent_occurred_at,consent_evidence_hash,content_ref,correlation_id,campaign_identity,campaign_snapshot)VALUES('sp3t3-starvation',fid,c,v,due,1,'followup-en','due',s,'sp3t3-starve-'||lpad(idx::text,3,'0'),encode(digest(request_payload::text,'sha256'),'hex'),1,1,sent_at,release_version,policy_version,knowledge_version,consent_at,consent_hash,'followup-en',corr,campaign_id,campaign_data);
 END LOOP;
END$sp3t3_starvation_fixture$;

DO $sp3t3_correction_boundaries$
DECLARE rt text:=current_setting('sf.rt');op text:=current_setting('sf.op');sch text:=current_setting('sf.sch');fw uuid;f followups;r jsonb;r2 jsonb;c uuid;v uuid;fid uuid;
BEGIN
 SELECT work_id INTO fw FROM schedule_followups(sch,clock_timestamp())WHERE account_ref='sp3t3-starvation'ORDER BY work_id LIMIT 1;ASSERT fw IS NOT NULL,'SP3-T3 fair due cursor produced no materialized child';SELECT*INTO f FROM followups WHERE(account_ref,intent_id)=('sp3t3-starvation',fw);BEGIN ALTER TABLE contact_identifiers DISABLE TRIGGER contact_identifier_immutable;UPDATE contact_identifiers SET active=false,retired_at=clock_timestamp()WHERE(account_ref,contact_id,channel,provider)=(f.account_ref,f.contact_id,'whatsapp','meta')AND active;ASSERT followup_final_authorization_reason(f.account_ref,fw)='contact_identifier_missing','SP3-T3 provider-call-start authorization ignored missing current WhatsApp Meta identity';RAISE EXCEPTION'rollback correction identity fixture';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback correction identity fixture'THEN RAISE;END IF;END;ASSERT EXISTS(SELECT 1 FROM scheduler_cursors WHERE name='followup-due'AND last_sort_at>'-infinity'),'SP3-T3 due cursor did not persist progress';
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t3-state-boundary","contact_ref":"sp3t3-state-boundary","body":"hello"}');c:=(r->>'contact_id')::uuid;v:=(r->>'conversation_id')::uuid;ASSERT set_conversation_state(op,'test-account',v)->>'reason'='invalid_input','SP3-T3 conversation state accepted an all-null no-op';ASSERT set_conversation_state(op,'test-account',v,'deleted')->>'reason'='invalid_input','SP3-T3 operational state API accepted deleted';r2:=set_conversation_state(op,'test-account',v,'opted_out');ASSERT(r2->>'ok')::bool;r2:=set_conversation_state(op,'test-account',v,'active');ASSERT r2->>'reason'='lifecycle_terminal'AND(SELECT lifecycle='opted_out'FROM conversations WHERE(account_ref,id)=('test-account',v)),'SP3-T3 terminal lifecycle was reactivated';
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t3-staging-guc-seed","contact_ref":"sp3t3-staging-guc","body":"hello"}');c:=(r->>'contact_id')::uuid;v:=(r->>'conversation_id')::uuid;INSERT INTO followups(account_ref,contact_id,conversation_id,due_at,expected_version)VALUES('test-account',c,v,clock_timestamp()+interval'1 hour',(SELECT version FROM conversations WHERE(account_ref,id)=('test-account',v)))RETURNING id INTO fid;PERFORM set_config('salesflow.staging_ingest','on',true);r2:=ingest(rt,'{"account_ref":"test-account","provider_id":"sp3t3-staging-guc-reply","contact_ref":"sp3t3-staging-guc","body":"reply"}');ASSERT(r2->>'accepted')::bool AND(SELECT state='cancelled'AND reason='customer_replied'FROM followups WHERE(account_ref,id)=('test-account',fid)),'SP3-T3 caller-set staging GUC bypassed reply cancellation';
 INSERT INTO followups(account_ref,contact_id,conversation_id,due_at,expected_version)VALUES('test-account',c,v,clock_timestamp()+interval'1 hour',(SELECT version FROM conversations WHERE(account_ref,id)=('test-account',v)))RETURNING id INTO fid;BEGIN UPDATE followups SET state='call_started',intent_id=NULL WHERE(account_ref,id)=('test-account',fid);ASSERT false,'SP3-T3 call_started accepted without intent_id';EXCEPTION WHEN check_violation THEN NULL;END;BEGIN UPDATE followups SET state='reconciliation_required',intent_id=NULL WHERE(account_ref,id)=('test-account',fid);ASSERT false,'SP3-T3 reconciliation_required accepted without intent_id';EXCEPTION WHEN check_violation THEN NULL;END;
END$sp3t3_correction_boundaries$;

DO $$BEGIN
 BEGIN UPDATE conversations SET lifecycle='invalid'WHERE id=(SELECT id FROM conversations LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE turns SET state='invalid'WHERE inbound_id=(SELECT inbound_id FROM turns LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE intents SET kind='invalid'WHERE id=(SELECT id FROM intents LIMIT 1);ASSERT false;EXCEPTION WHEN raise_exception THEN NULL;END;
 BEGIN UPDATE intents SET state='invalid'WHERE id=(SELECT id FROM intents LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE intents SET provider_status='invalid'WHERE id=(SELECT id FROM intents LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE intents SET expected_version=expected_version+1 WHERE id=(SELECT id FROM intents LIMIT 1);ASSERT false;EXCEPTION WHEN raise_exception THEN NULL;END;
 BEGIN UPDATE intents SET body='mutated'WHERE id=(SELECT id FROM intents LIMIT 1);ASSERT false;EXCEPTION WHEN raise_exception THEN NULL;END;
 BEGIN UPDATE intents SET provenance='{}'WHERE id=(SELECT id FROM intents WHERE provenance<>'{}'LIMIT 1);ASSERT false;EXCEPTION WHEN raise_exception THEN NULL;END;
 BEGIN DELETE FROM intents WHERE id=(SELECT id FROM intents LIMIT 1);ASSERT false;EXCEPTION WHEN raise_exception THEN NULL;END;
 BEGIN UPDATE followups SET state='invalid'WHERE id=(SELECT id FROM followups WHERE state IN('due','claimed','retry','intent_created')LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE handoffs SET state='invalid'WHERE id=(SELECT id FROM handoffs LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE deletion_requests SET state='invalid'WHERE id=(SELECT id FROM deletion_requests LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE deletion_targets SET state='invalid'WHERE request_id=(SELECT request_id FROM deletion_targets LIMIT 1);ASSERT false;EXCEPTION WHEN check_violation THEN NULL;END;
END$$;
DO $review_boundaries$
DECLARE rt text:=current_setting('sf.rt');op text:=current_setting('sf.op');r jsonb;r2 jsonb;c uuid;v uuid;m uuid;other_v uuid;h uuid;claim_value uuid;before_count bigint;
BEGIN
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"review-consent","contact_ref":"review-consent","body":"hello"}');c:=(r->>'contact_id')::uuid;v:=(r->>'conversation_id')::uuid;
 ASSERT set_consent(rt,'test-account',c,NULL,'evidence')->>'reason'='invalid_input','NULL consent status was accepted';
 r2:=set_consent(rt,'test-account',c,'granted',repeat(chr(233),4096));ASSERT(r2->>'ok')::bool,'exact 8192-byte consent evidence was rejected';
 ASSERT set_consent(rt,'test-account',c,'granted',repeat(chr(233),4097))->>'reason'='invalid_input','over-limit UTF-8 consent evidence was accepted';
 SELECT count(*)INTO before_count FROM consent_events WHERE(account_ref,contact_id)=('test-account',c);r2:=operations(op,'test-account',jsonb_build_object('action','delete','contact_id',c));ASSERT r2->>'terminal'='deleted';r2:=set_consent(rt,'test-account',c,'granted','post-delete plaintext');ASSERT r2->>'reason'='deleted'AND(SELECT count(*)=before_count FROM consent_events WHERE(account_ref,contact_id)=('test-account',c)),'post-deletion consent wrote new plaintext';
 ASSERT operations(op,'test-account','{"action":"retention","at":"not-a-time"}')->>'reason'='invalid_input','malformed retention timestamp was not typed';
 ASSERT enforce_retention(op,'test-account',clock_timestamp()+interval'1 minute')->>'reason'='invalid_input','future retention timestamp was accepted';
 ASSERT NOT validate_config('model',jsonb_build_object('accountRef','test-account','kind','model','version','bounded','selection','synthetic-local','productionEnabled',false,'allowedClaims',jsonb_build_array(repeat('x',1025)))),'oversized config string was accepted';
 ASSERT NOT validate_config('model',jsonb_build_object('accountRef','test-account','kind','model','version','bounded-array','selection','synthetic-local','productionEnabled',false,'allowedClaims',(SELECT jsonb_agg('x'||n)FROM generate_series(1,101)n))),'oversized config array was accepted';
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"review-source-one","contact_ref":"review-source-one","body":"hello"}');c:=(r->>'contact_id')::uuid;v:=(r->>'conversation_id')::uuid;m:=(r->>'inbound_id')::uuid;r2:=ingest(rt,'{"account_ref":"test-account","provider_id":"review-source-two","contact_ref":"review-source-two","body":"hello"}');other_v:=(r2->>'conversation_id')::uuid;
 BEGIN INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence)VALUES('test-account',c,other_v,m,'mismatch','synthetic-sales',clock_timestamp()+interval'1 hour','{}');ASSERT false,'mismatched Handoff tuple was accepted';EXCEPTION WHEN foreign_key_violation THEN NULL;END;
 BEGIN DELETE FROM inbound_messages WHERE(account_ref,id)=('test-account',m);ASSERT false,'inbound evidence deletion was accepted';EXCEPTION WHEN raise_exception THEN NULL;END;
 INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence)VALUES('test-account',c,v,m,'trusted-time','synthetic-sales',clock_timestamp()+interval'1 hour','{}')RETURNING id INTO h;r2:=claim_handoff(rt,'test-account',h,'2999-01-01');ASSERT(r2->>'ok')::bool;claim_value:=(r2->>'claim')::uuid;ASSERT(SELECT claim_until<clock_timestamp()+interval'10 minutes'FROM handoffs WHERE(account_ref,id)=('test-account',h)),'Handoff claim trusted caller time';ASSERT finish_handoff(rt,'test-account',h,claim_value,NULL)->>'reason'='invalid_outcome','NULL Handoff outcome was accepted';
END$review_boundaries$;
-- September 5 caller-path regressions are rolled back to preserve the canonical fixtures.
BEGIN;
DO $september_review$
DECLARE rt text:=current_setting('sf.rt');op text:=current_setting('sf.op');sch text:=current_setting('sf.sch');r jsonb;duplicate_result jsonb;doc jsonb;conv uuid;contact uuid;inbound uuid;seen bool:=false;batch record;n int;long_id text;
BEGIN
 SELECT body INTO doc FROM config_docs WHERE account_ref='test-account'AND kind='consent_templates'AND active;
 ASSERT validate_config('consent_templates',doc),'baseline consent config invalid';
 ASSERT NOT validate_config('consent_templates',jsonb_set(doc,'{optOutSignals}','["STOP"]')),'uppercase opt-out signal accepted';
 ASSERT NOT validate_config('consent_templates',jsonb_set(doc,'{optOutSignals}','[" stop "]')),'padded opt-out signal accepted';
 ASSERT NOT validate_config('consent_templates',jsonb_set(doc,'{humanSignals}','["Talk  to human"]')),'noncanonical human signal accepted';
 ASSERT operations('invalid-token',NULL,'{"action":"account_enabled","enabled":false}')->>'reason'='unauthorized','invalid management token accepted';
 ASSERT operations(rt,NULL,'{"action":"account_enabled","enabled":false}')->>'reason'='unauthorized','runtime token gained management authority';
 ASSERT operations(op,'account-b','{"action":"account_enabled","enabled":false}')->>'reason'='unauthorized','explicit cross-account management accepted';
 r:=operations(op,NULL,'{"action":"account_enabled","enabled":false}');ASSERT(r->>'ok')::bool AND NOT(SELECT enabled FROM accounts WHERE id='test-account'),'webhook NULL-account disable failed';
 r:=operations(op,NULL,'{"action":"account_enabled","enabled":true}');ASSERT(r->>'ok')::bool AND(SELECT enabled FROM accounts WHERE id='test-account'),'disabled-account webhook re-enable failed';
 SELECT string_agg(md5(g.value::text),'')INTO long_id FROM generate_series(1,200)AS g(value);
 r:=ingest(rt,jsonb_build_object('account_ref','test-account','provider_id',long_id,'contact_ref','review-id-too-long','body','hello'));
 ASSERT r->>'reason'='invalid'AND NOT EXISTS(SELECT 1 FROM contact_identifiers WHERE account_ref='test-account'AND external_ref='review-id-too-long'),'oversized indexed ID was not rejected before writes';
 r:=ingest(rt,jsonb_build_object('account_ref','test-account','provider_id',repeat(chr(233),513),'contact_ref','review-id-multibyte','body','hello'));
 ASSERT r->>'reason'='invalid','provider ID bound counted characters instead of bytes';
 r:=ingest(rt,jsonb_build_object('account_ref','test-account','provider_id',repeat('a',1024),'contact_ref','review-id-limit','body','hello'));
 ASSERT(r->>'accepted')::bool,'1024-byte provider ID boundary rejected';
 r:=ingest(rt,'{"account_ref":"test-account","provider_id":"review-pending-recovery","contact_ref":"review-pending-recovery","body":"hello"}');
 ASSERT(r->>'created')::bool;conv:=(r->>'conversation_id')::uuid;contact:=(r->>'contact_id')::uuid;inbound:=(r->>'inbound_id')::uuid;
 PERFORM set_consent(rt,'test-account',contact,'granted','pending recovery fixture');
 duplicate_result:=ingest(rt,'{"account_ref":"test-account","provider_id":"review-pending-recovery","contact_ref":"review-pending-recovery","body":"hello"}');
 ASSERT duplicate_result->>'created'='false'AND(duplicate_result->>'conversation_id')::uuid=conv,'duplicate lost durable conversation routing';
 ASSERT complete_turn(op,'test-account',conv)->>'reason'='wrong_account','operator gained turn authority';
 ASSERT complete_turn(current_setting('sf.rt2'),'test-account',conv)->>'reason'='wrong_account','cross-account turn recovery accepted';
 -- An expired claim must be discoverable just like the pending crash window.
 UPDATE turns SET state='claimed',claim=gen_random_uuid(),claim_until=clock_timestamp()-interval'1 second'WHERE account_ref='test-account'AND inbound_id=inbound;
 FOR n IN 1..50 LOOP
  FOR batch IN SELECT*FROM schedule_work(sch,clock_timestamp())LOOP
   IF(batch.account_ref,batch.work_id,batch.workflow_id)=('test-account',conv,'salesflow-wf-02')THEN seen:=true;END IF;
  END LOOP;
  EXIT WHEN seen;
 END LOOP;
 ASSERT seen,'durable scheduler omitted unfinished conversation';
 r:=complete_turn(sch,'test-account',conv);ASSERT r->>'terminal'='created','scheduler turn recovery failed: '||r::text;
 r:=complete_turn(sch,'test-account',conv);ASSERT r->>'terminal'='nothing','repeated recovery did not become idle';
 ASSERT(SELECT count(*)=1 FROM intents WHERE account_ref='test-account'AND source_id=inbound),'recovery duplicated outbound intent';
 ASSERT(SELECT state='completed'FROM turns WHERE account_ref='test-account'AND inbound_id=inbound),'recovery did not complete turn';
END$september_review$;
ROLLBACK;
SELECT'SCENARIOS='||string_agg(id,','ORDER BY id)FROM evidence;
